INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 5, 'theory', 'Quiz: processes and limits');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 0, 'An ordinary user runs ulimit -n 4096 in bash without -S or -H. What happens?', '["Only the soft value changes, the hard one stays", "Both the soft and the hard value change; without administrator rights the hard one cannot be raised again", "The command fails: only root changes limits", "The system-wide limit for all users changes"]', 1, 'Without flags the builtin changes both values. An ordinary user can only lower the hard one, and cannot raise it back. To change just the soft one you need -S. The limit applies only in this shell and its children.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 1, 'An administrator put nofile 65536 for nginx in /etc/security/limits.conf, but the nginx service started by systemd still runs with 1024. Why?', '["limits.conf is read only at server reboot", "The value 65536 is above fs.file-max", "The soft value cannot be set in limits.conf", "A service does not go through a PAM login session, so the unit sets the limits: LimitNOFILE="]', 3, 'limits.conf is applied by the pam_limits module when a login session opens. A service started by systemd does not pass through it. Its limits come from LimitNOFILE= in the unit (or a drop-in) and DefaultLimitNOFILE= in system.conf.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 2, 'What does an oom_score_adj of -1000 mean for a process?', '["The OOM killer will never choose this process as a victim", "The process is killed first because it is the most important", "The process gets the highest CPU priority", "The process may use unlimited memory, but the kernel slows it down"]', 0, 'A value of -1000 excludes the process from victim selection. +1000 makes it the first candidate. oom_score_adj does not affect CPU priority; that is the separate nice setting.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 3, 'An ordinary user runs renice -n -5 -p on their own process with nice 0. How does it end by default?', '["Success: your own process can be changed freely", "The process gets nice 5 instead of -5", "It is refused with a permission error: lowering nice needs privileges or a suitable RLIMIT_NICE", "The kernel silently ignores the command and prints nothing"]', 2, 'Any owner may raise the nice value (lower the priority). Lowering it needs the CAP_SYS_NICE privilege or RLIMIT_NICE, which by default is zero and does not allow it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 4, 'What happens with vm.overcommit_memory=2 when the sum of committed memory reaches CommitLimit?', '["The kernel starts the OOM killer and kills the largest process", "The kernel allocates from swap without limits", "The system reboots", "New memory allocations fail, no processes are killed"]', 3, 'In strict mode the ceiling is swap plus a share of RAM. Exceeding it makes the allocation fail (malloc or mmap reports a refusal) instead of killing a process later.');
